:root{color-scheme:dark;--bg:#08090b;--panel:#111217;--text:#f4f2f7;--muted:#9995a1;--violet:#a68aff;--line:rgba(242,239,250,.14);--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif;scroll-behavior:smooth;scroll-padding-top:86px}
*{box-sizing:border-box}html{min-width:320px;background:var(--bg);scroll-behavior:smooth}body{margin:0;min-width:320px;overflow-x:hidden;background:var(--bg);color:var(--text);font-family:var(--sans);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}button,input,select,textarea{font:inherit}button,a{color:inherit}a{text-decoration:none}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--violet);outline-offset:4px}::selection{background:#aa91ff;color:#08090b}.scroll-progress{position:fixed;z-index:100;top:0;left:0;width:100%;height:2px;background:#aa91ff;transform:scaleX(0);transform-origin:left;pointer-events:none}.site-header{position:fixed;z-index:60;top:0;left:0;right:0;height:78px;padding:0 5.2vw;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,9,11,.94),rgba(8,9,11,.66) 70%,transparent);backdrop-filter:blur(5px)}.wordmark{display:flex;align-items:center;gap:10px;min-width:170px}.wordmark-icon{font-size:32px;line-height:1;font-weight:700;letter-spacing:-4px}.wordmark-icon span{color:var(--violet)}.wordmark-name{font-size:9px;line-height:1.35;letter-spacing:.13em;font-weight:600}.desktop-nav{display:flex;align-items:center;gap:clamp(19px,3vw,45px)}.desktop-nav a,.skip-intro,.sound-toggle{font:9px var(--mono);letter-spacing:.1em;color:#c7c3ce;transition:color .2s}.desktop-nav a:hover,.skip-intro:hover{color:white}.nav-contact{display:flex;gap:5px;align-items:center}.skip-intro{display:flex;gap:7px;align-items:center;border-bottom:1px solid #ffffff66;padding-bottom:6px;color:white}.sound-toggle{display:flex;align-items:center;gap:8px;border:0;background:none;padding:8px 0;cursor:pointer}.sound-icon{width:15px;height:15px;display:inline-grid;place-items:center;color:#ddd}.sound-toggle[aria-pressed='true'] .sound-icon{color:var(--violet)}.sound-state{width:5px;height:5px;border-radius:50%;background:#64616a}.sound-toggle[aria-pressed='true'] .sound-state{background:var(--violet);box-shadow:0 0 10px var(--violet)}.mobile-actions,.menu-toggle,.mobile-menu{display:none}.hero{position:relative;min-height:max(740px,100svh);height:900px;max-height:1100px;overflow:hidden;background:radial-gradient(ellipse at 72% 46%,rgba(43,31,69,.22),transparent 36%),var(--bg)}.hero:after{content:'';position:absolute;z-index:2;inset:0;pointer-events:none;background:linear-gradient(90deg,#08090b 0%,rgba(8,9,11,.84) 34%,rgba(8,9,11,.11) 76%,rgba(8,9,11,.32)),linear-gradient(0deg,#08090b 0%,transparent 28%)}.grain{position:absolute;z-index:3;inset:0;opacity:.13;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.2'/%3E%3C/svg%3E")}.hero-topline{position:absolute;z-index:5;top:112px;left:5.2vw;right:5.2vw;display:flex;justify-content:space-between;color:#898590;font:8px var(--mono);letter-spacing:.14em}.live-dot{display:inline-block;width:6px;height:6px;margin-right:8px;border-radius:50%;background:#a78cff;box-shadow:0 0 10px #a78cff99}.three-scene{position:relative;overflow:hidden}.hero-scene{position:absolute;z-index:1;top:0;right:0;width:68%;height:100%;opacity:.93}.three-scene canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.css-fallback{position:absolute;top:50%;left:50%;width:min(42vw,420px);aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle at 31% 25%,#eeeaf1 0,#aaa5b1 8%,#534d60 24%,#201c28 54%,#08090b 72%);box-shadow:inset -23px -20px 35px #030304,0 0 90px #7951bd2b}.has-webgl .css-fallback{display:none}.hero-copy{position:absolute;z-index:5;top:51%;left:10.3vw;transform:translateY(-43%);width:min(800px,78vw)}.eyebrow{margin:0 0 24px;color:#a7a3ad;font:9px var(--mono);letter-spacing:.13em}.eyebrow strong{color:#eeeaf2;font-weight:400}.hero-eyebrow{width:min(465px,90%);display:flex;justify-content:space-between;margin-bottom:30px}.hero-title{margin:0;font-size:clamp(54px,8.3vw,121px);font-weight:500;line-height:.87;letter-spacing:-.079em;text-transform:uppercase}.hero-title span{display:block;white-space:nowrap}.hero-title span:nth-child(2){font-weight:600}.hero-title .comma{color:var(--violet)}.hero-title em{display:block;margin-top:25px;color:#c2bdca;font-size:clamp(23px,3.3vw,47px);font-weight:400;font-style:normal;letter-spacing:-.055em;text-transform:none}.hero-bottom{display:flex;width:min(620px,100%);align-items:flex-end;justify-content:space-between;margin-top:46px}.hero-tagline{margin:0;color:#aaa7b1;font-size:12px;line-height:1.8}.hero-tagline strong{color:#f3f1f6;font-weight:500}.begin-button{display:flex;align-items:center;gap:11px;font:9px var(--mono);letter-spacing:.1em}.begin-icon{width:40px;height:40px;display:grid;place-items:center;border:1px solid #ffffff66;border-radius:50%;transition:transform .25s,background .25s,color .25s}.begin-button:hover .begin-icon{transform:rotate(45deg);background:#eeeaf2;color:#111}.hero-edge{position:absolute;z-index:5;right:4vw;top:43%;writing-mode:vertical-rl;color:#898590;font:8px var(--mono);letter-spacing:.18em}.hero-scroll{position:absolute;z-index:5;left:5.2vw;bottom:30px;color:#898590;font:8px var(--mono);letter-spacing:.13em}.hero-scroll span{padding-left:12px;color:#eee}.story-section{position:relative}.awakening{min-height:720px;padding:125px 10vw 100px;overflow:hidden;background:linear-gradient(180deg,#08090b,#0e0d13 55%,#090a0d)}.awakening-inner{display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:6vw;max-width:1150px;margin:auto}.awakening-art{position:relative;height:420px;display:grid;place-items:center}.awakening-core{position:relative;z-index:2;width:170px;height:170px;border-radius:34% 66% 56% 44%/42% 35% 65% 58%;background:radial-gradient(circle at 30% 23%,#ebe8f5 0,#9993a4 9%,#393746 28%,#15151c 56%,#090a0d 70%);box-shadow:inset -15px -18px 32px #050507,inset 7px 8px 18px #ded7f655,0 0 85px #774cd433,0 0 180px #4730712b;animation:float 8s ease-in-out infinite}.awakening-core:after{content:'';position:absolute;inset:27% 20%;border:1px solid #dad1f25c;border-radius:50%;transform:rotate(-30deg);box-shadow:0 0 18px #b79aff38}.awakening-orbit{position:absolute;width:340px;height:175px;border:1px solid #b1a1dc38;border-radius:50%;transform:rotate(-26deg)}.awakening-orbit.alt{width:360px;height:125px;transform:rotate(63deg);border-color:#c3c1cf26}.awakening-star{position:absolute;top:18%;left:70%;color:#d6caff;font-size:22px;text-shadow:0 0 16px #ac85ff;animation:turn 22s linear infinite}.micro-note{position:absolute;color:#9994a2;font:8px/1.7 var(--mono);letter-spacing:.12em}.note-top{top:42px;left:15px}.note-bottom{right:8px;bottom:38px}.awakening-copy{max-width:480px}.awakening-copy h2,.section-heading h2,.work-heading h2{margin:0;font-size:clamp(38px,5vw,68px);font-weight:500;line-height:.99;letter-spacing:-.07em}.awakening-copy h2 em,.section-heading h2 em,.work-heading h2 em{color:#a49bad;font-weight:400;font-style:normal}.body-copy{max-width:410px;margin:24px 0 30px;color:#a19da8;font-size:13px;line-height:1.85}.text-link{display:inline-flex;align-items:center;gap:13px;color:#f0edf4;font:8px var(--mono);letter-spacing:.13em}.text-link span{font-size:16px;transition:transform .2s}.text-link:hover span{transform:translateX(5px)}.side-note{position:absolute;right:4.7vw;bottom:52px;color:#77737f;writing-mode:vertical-rl;font:8px var(--mono);letter-spacing:.15em}.portal-section{height:780px;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at center,#171321 0,#0b0b10 45%,#08090b 77%)}.portal-section:before,.portal-section:after{position:absolute;top:24%;left:8%;width:84%;height:1px;background:linear-gradient(90deg,transparent,#8a70bc44,transparent);content:''}.portal-section:after{top:79%}.portal-scene{position:absolute;top:48%;left:50%;width:min(720px,80vw);height:min(650px,82vh);transform:translate(-50%,-50%);opacity:.9}.portal-halo{position:absolute;width:500px;height:500px;border-radius:50%;background:#6e46b51a;filter:blur(85px)}.portal-caption{position:relative;z-index:2;margin-top:5px;text-align:center;text-shadow:0 2px 22px #08090b}.portal-caption .eyebrow{font-size:8px}.portal-caption h2{margin:24px 0 18px;font-size:clamp(55px,8vw,104px);font-weight:600;line-height:.75;letter-spacing:-.09em}.portal-caption h2 span{font-size:.47em;font-weight:400;letter-spacing:.025em}.portal-caption>p:not(.eyebrow){color:#bdb8c7;font:8px var(--mono);letter-spacing:.22em}.round-link{width:42px;height:42px;display:grid;place-items:center;margin:31px auto 0;border:1px solid #d5cedd66;border-radius:50%;font-size:19px;transition:transform .2s,background .2s,color .2s}.round-link:hover{transform:translateY(4px);background:#e5e0ee;color:#0a0910}.portal-side{position:absolute;right:4.5vw;top:48%;color:#8d8796;writing-mode:vertical-rl;font:8px var(--mono);letter-spacing:.16em}.design-section{padding:130px 10.3vw 95px;background:#0b0c10}.section-heading{display:flex;max-width:1200px;align-items:flex-end;justify-content:space-between;gap:35px;margin:0 auto 52px}.section-heading .eyebrow,.work-heading .eyebrow{margin-bottom:22px}.section-heading h2{font-size:clamp(52px,7vw,88px)}.section-intro{max-width:300px;margin:0 0 5px;color:#a09da7;font-size:12px;line-height:1.9}.discipline-row{display:flex;max-width:1200px;flex-wrap:wrap;gap:9px 18px;margin:0 auto 18px;color:#85818d;font:8px var(--mono);letter-spacing:.08em}.discipline-row span:not(:last-child):after{padding-left:16px;color:#a98dff;content:'·'}.feature-grid{display:grid;max-width:1200px;grid-template-columns:1.45fr .8fr;align-items:start;gap:15px;margin:0 auto}.feature-button{display:block;min-width:0;padding:0;border:0;background:none;text-align:left}.feature-button.second{margin-top:76px}.project-art{position:relative;isolation:isolate;display:flex;min-height:200px;align-items:center;justify-content:center;overflow:hidden;background:#15141b}.project-art:after{position:absolute;z-index:-1;inset:0;background:linear-gradient(135deg,transparent 40%,rgba(255,255,255,.035));content:''}.project-art.has-image img{z-index:0}.project-art.has-image>*:not(img):not(.art-label){display:none}.feature-button:first-child .project-art{height:410px}.feature-button.second .project-art{height:300px}.art-label{position:absolute;bottom:13px;left:16px;color:#ece9f2a1;font:7px var(--mono);letter-spacing:.1em}.art-orb{position:relative;width:38%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 30% 25%,#f2f0f2,#aaa9b0 7%,#63626c 23%,#212128 53%,#090a0c 71%);box-shadow:inset -14px -14px 22px #050507,0 5px 58px #9b87ff40}.art-orb:before,.art-orb:after{position:absolute;top:34%;left:-30%;width:160%;height:34%;border:1px solid #d3ceda77;border-radius:50%;content:'';transform:rotate(-32deg)}.art-orb:after{top:36%;left:-39%;width:180%;height:26%;border-color:#8d7cac8a;transform:rotate(57deg)}.art-type{color:#17151a;background:#e9e5db}.art-type:before{position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 33px,#1b182214 34px);content:''}.art-type-word{z-index:1;font-size:clamp(68px,13vw,170px);font-weight:700;line-height:.68;letter-spacing:-.115em;text-shadow:8px 8px #b8b1a7;transform:rotate(-8deg)}.art-type-mark{position:absolute;top:14%;right:15%;color:#8266a7;font:italic 50px Georgia}.art-type .art-label,.art-poster .art-label{color:#38353c}.art-geo{background:#292838}.geo-ring{position:absolute;width:54%;aspect-ratio:1;border:1px solid #cbbcff;border-radius:40% 60% 48% 52%;box-shadow:inset 0 0 35px #bca6ff26,0 0 37px #8865d23c;transform:rotate(37deg)}.geo-block{width:33%;height:35%;background:linear-gradient(142deg,#d8d3de,#62586e 48%,#211d2a);box-shadow:16px 20px 40px #07060b99;transform:rotate(-30deg)}.geo-caption{position:absolute;top:22px;color:#ccc4df;font:8px var(--mono);letter-spacing:.15em}.art-light{background:radial-gradient(ellipse at 48% 45%,#423079,#171221 55%,#0b0a0e)}.light-shape{width:42%;height:62%;background:linear-gradient(145deg,#ffc8e6,#a97dff 37%,#48239e 72%,#140b2e);clip-path:polygon(50% 0,78% 28%,68% 42%,100% 70%,61% 100%,19% 79%,0 44%,33% 36%);filter:drop-shadow(0 0 50px #a865ff77);transform:rotate(10deg)}.light-label{position:absolute;top:20px;right:18px;font:8px var(--mono);letter-spacing:.18em}.art-orbit{background:radial-gradient(ellipse at center,#35313b,#101015 72%)}.orbit-shape{width:37%;aspect-ratio:1;border-radius:42% 58% 52% 48%;background:radial-gradient(circle at 33% 25%,#ddd8e7,#888493 13%,#37333e 44%,#131218 71%);box-shadow:inset -16px -15px 23px #08070b,0 0 50px #a893da31;transform:rotate(28deg)}.orbit-line{position:absolute;width:63%;height:27%;border:2px solid #c8c2d5a0;border-radius:50%;box-shadow:0 0 13px #c3a6ff55;transform:rotate(-36deg)}.art-poster{color:#171914;background:#e1f15d}.poster-signal{position:absolute;z-index:1;top:12%;left:10%;font-size:clamp(43px,7vw,94px);font-weight:700;line-height:.77;letter-spacing:-.095em}.poster-sun{position:absolute;right:12%;bottom:0;width:44%;aspect-ratio:1;border-radius:50%;background:#fa654c;box-shadow:0 0 0 18px #fa654c42,0 0 0 38px #fa654c18}.feature-meta{display:flex;justify-content:space-between;align-items:center;padding:14px 1px;color:#a09da7;font:7px var(--mono);letter-spacing:.09em}.feature-meta strong{color:#e8e4ee;font-weight:400}.feature-meta span:last-child{display:flex;align-items:center;gap:8px}.feature-button .project-art{transition:filter .35s}.feature-button:hover .project-art{filter:brightness(1.13)}.section-endnote{display:flex;max-width:1200px;justify-content:space-between;margin:59px auto 0;padding-top:15px;border-top:1px solid var(--line);color:#817d88;font:8px var(--mono);letter-spacing:.1em}.section-endnote a{color:#d9d5df}.motion-section{display:grid;min-height:710px;grid-template-columns:.9fr 1.1fr;align-items:center;gap:4vw;padding:100px 10.3vw;overflow:hidden;background:radial-gradient(ellipse at 74% 48%,#171321,#0a0a0e 49%,#08090b 75%)}.motion-copy{position:relative;z-index:2}.motion-copy h2{margin:0 0 25px;font-size:clamp(50px,6.7vw,85px);font-weight:500;line-height:.88;letter-spacing:-.08em}.motion-copy h2 em{color:#a398b5;font-weight:400;font-style:normal}.motion-copy h3{margin:0 0 18px;font-size:13px;font-weight:500}.motion-copy>p:not(.eyebrow){max-width:390px;color:#98949f;font-size:12px;line-height:1.8}.discipline-pills{display:flex;max-width:450px;flex-wrap:wrap;gap:8px;margin-top:25px}.discipline-pills span{padding:8px 9px;border:1px solid #bcb3c321;color:#b8b1c2;font:7px var(--mono);letter-spacing:.06em}.motion-render{position:relative;height:475px}.motion-render .portal-scene{position:absolute;inset:0;width:100%;height:100%;transform:none}.render-caption{position:absolute;right:10px;bottom:10px;left:10px;display:flex;justify-content:space-between;color:#8b8592;font:7px var(--mono);letter-spacing:.1em}.founder-section{display:grid;min-height:735px;grid-template-columns:.83fr 1fr;align-items:center;gap:9vw;padding:115px 12vw 125px;background:#0d0e12}.founder-visual{position:relative}.portrait-placeholder{position:relative;max-width:355px;height:445px;overflow:hidden;border:1px solid #ffffff0c;background:radial-gradient(ellipse at 52% 39%,#292734,#14141a 57%,#101115)}.portrait-placeholder:before{position:absolute;inset:0;background:linear-gradient(150deg,transparent 40%,#a085ff12);content:''}.placeholder-frame{position:absolute;z-index:2;top:18px;left:17px;padding-left:10px;border-left:1px solid #e9e0ff75;color:#c5bfce;font:8px/1.7 var(--mono);letter-spacing:.1em}.silhouette{position:absolute;bottom:0;left:50%;width:78%;height:78%;filter:drop-shadow(0 0 50px #9a7cd82c);transform:translateX(-50%)}.silhouette-head{position:absolute;z-index:2;top:3%;left:37%;width:29%;height:36%;border-radius:47% 48% 44% 45%;background:linear-gradient(115deg,#5f5b6b,#292831 42%,#15151b 82%)}.silhouette-body{position:absolute;bottom:-7%;left:4%;width:94%;height:68%;border-radius:49% 50% 0 0;background:linear-gradient(110deg,#36343f,#14151a 53%,#292630);clip-path:polygon(31% 0,68% 0,83% 23%,100% 100%,0 100%,16% 25%)}.photo-label{position:absolute;z-index:2;bottom:14px;left:15px;color:#a8a3b0;font:7px var(--mono);letter-spacing:.1em}.founder-index{position:absolute;bottom:15px;left:-21px;color:#a69db5;writing-mode:vertical-rl;font:8px var(--mono);letter-spacing:.15em}.founder-copy{max-width:530px}.founder-copy h2{margin:14px 0 22px;font-size:clamp(62px,8.4vw,106px);font-weight:600;line-height:.76;letter-spacing:-.1em}.founder-copy h2 em{color:#a095b1;font-style:normal}.founder-role{color:#cbc5d2;font:8px var(--mono);letter-spacing:.15em}.founder-intro{max-width:430px;margin:28px 0;color:#aaa6b0;font-size:13px;line-height:1.85}.founder-divider{height:1px;margin:34px 0 22px;background:var(--line)}.founder-detail{display:grid;grid-template-columns:145px 1fr;gap:15px;margin:14px 0}.founder-detail strong{color:#8f899a;font:8px var(--mono);letter-spacing:.09em}.founder-detail p{margin:0;color:#c3bec9;font-size:10px;line-height:1.65}.editable-note{margin-top:25px;color:#75717b;font:8px var(--mono);line-height:1.6}.work-section{padding:125px 10.3vw 115px;background:#090a0d}.work-heading{display:flex;max-width:1200px;align-items:flex-end;justify-content:space-between;margin:0 auto 43px}.work-heading h2{font-size:clamp(55px,7.2vw,89px)}.work-heading>p{margin:0 0 5px;color:#9a96a0;font-size:11px;line-height:1.9}.filters{display:flex;max-width:1200px;flex-wrap:wrap;gap:7px;margin:0 auto 26px}.filter-button{padding:10px 13px;border:1px solid #ffffff24;background:none;color:#9e99a6;font:7px var(--mono);letter-spacing:.06em;transition:background .2s,color .2s,border-color .2s}.filter-button:hover{border-color:#b19aff;color:white}.filter-button[aria-pressed='true']{border-color:#eae6f0;background:#eae6f0;color:#111016}.project-grid{display:grid;max-width:1200px;grid-template-columns:1fr 1fr;column-gap:18px;row-gap:57px;margin:0 auto}.project-card{position:relative;display:block;min-width:0}.project-card-button{display:block;width:100%;padding:0;border:0;background:none;text-align:left}.project-card:nth-child(even){margin-top:72px}.project-card .project-art{height:clamp(235px,33vw,420px);transition:transform .45s,filter .35s}.project-card:hover .project-art{transform:translateY(-5px);filter:brightness(1.12)}.project-card .project-art img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.project-meta{display:flex;align-items:center;justify-content:space-between;padding:15px 2px 0}.project-number{color:#98929f;font:7px var(--mono);letter-spacing:.09em}.project-title{display:block;margin:7px 0 0;font-size:18px;font-weight:500;letter-spacing:-.04em}.project-open{display:grid;width:34px;height:34px;place-items:center;border:1px solid #ffffff31;border-radius:50%;transition:background .2s,color .2s}.project-card:hover .project-open{background:#ece7f4;color:#111}.concept-flag{position:absolute;top:12px;right:12px;padding:7px 9px;background:#09090bd9;color:#c4bbc9;font:7px var(--mono);letter-spacing:.1em;pointer-events:none}.social-links{display:flex;gap:17px;margin-top:24px}.social-links a{color:#c7c0d1;font:7px var(--mono);letter-spacing:.09em}.social-links a:hover{color:#fff}.honesty-note{display:flex;max-width:1200px;align-items:center;gap:10px;margin:70px auto 0;padding-top:18px;border-top:1px solid var(--line);color:#85818b}.honesty-dot{width:6px;height:6px;flex:0 0 6px;border-radius:50%;background:#a28ae0}.honesty-note p{margin:0;font:8px/1.6 var(--mono)}.contact-section{min-height:900px;padding:115px 10.3vw 0;overflow:hidden;background:radial-gradient(ellipse at 79% 9%,#2b1f4a 0,#171225 13%,#0a0a0e 42%,#090a0d 71%)}.contact-orb{position:absolute;top:3%;right:13%;width:350px;height:350px;opacity:.75}.contact-orb div{position:absolute;inset:12%;border-radius:50%;background:radial-gradient(circle at 33% 24%,#fff5,#b099e2 5%,#544174 26%,#1a1425 59%,#0a090e 70%);box-shadow:inset -22px -20px 32px #07070a,0 0 110px #895fdb5c}.contact-orb i,.contact-orb b{position:absolute;top:37%;left:-18%;width:138%;height:27%;border:1px solid #d9c7ff77;border-radius:50%;transform:rotate(-28deg)}.contact-orb b{border-color:#bba5e951;transform:rotate(61deg)}.contact-heading{position:relative;z-index:2}.contact-heading h2{margin:0;font-size:clamp(41px,6vw,76px);font-weight:500;line-height:.97;letter-spacing:-.075em}.contact-heading h2 em{color:#b5a6d1;font-weight:400;font-style:normal}.contact-heading h3{margin:23px 0 0;color:#dad5e0;font-size:14px;font-weight:500}.contact-content{position:relative;z-index:2;display:grid;grid-template-columns:.75fr 1.25fr;gap:9vw;margin-top:76px;padding-bottom:110px}.contact-aside{display:flex;flex-direction:column;align-items:flex-start}.contact-aside>p{max-width:250px;margin:0 0 27px;color:#a19ca8;font-size:12px;line-height:1.9}.availability{display:flex;align-items:center;color:#d3ceda;font:8px var(--mono);letter-spacing:.1em}.contact-signoff{margin-top:auto;padding-top:55px;color:#88828e;font:8px/1.9 var(--mono);letter-spacing:.1em}.contact-form label{display:flex;flex-direction:column;gap:9px;color:#d6d0dc;font:8px var(--mono);letter-spacing:.07em}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px 20px;margin-bottom:25px}.contact-form input,.contact-form select,.contact-form textarea{width:100%;padding:10px 0 12px;border:0;border-bottom:1px solid #f5f0ff31;border-radius:0;outline:none;background:transparent;color:#eeebf2;font:11px var(--sans)}.contact-form textarea{resize:vertical}.contact-form input::placeholder,.contact-form textarea::placeholder{color:#706c77}.contact-form select{color:#aaa5b2}.contact-form option{background:#17161e}.contact-form input:focus,.contact-form select:focus,.contact-form textarea:focus{border-color:#b49aff}.contact-form>label{margin-top:4px}.form-footer{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-top:22px}.form-notice{max-width:340px;margin:0;color:#c5b4ff;font:8px/1.6 var(--mono)}.submit-button{display:inline-flex;min-height:46px;align-items:center;justify-content:center;gap:15px;padding:0 17px;border:0;background:#eeeaf2;color:#111015;font:8px var(--mono);letter-spacing:.1em;white-space:nowrap;transition:transform .2s,background .2s}.submit-button:hover{transform:translateY(-2px);background:#c5b0ff}.site-footer{position:relative;z-index:2;display:grid;min-height:80px;grid-template-columns:1.2fr 1.5fr 1fr 1fr;align-items:center;gap:14px;border-top:1px solid #ffffff24;color:#817b88;font:7px var(--mono);letter-spacing:.07em}.footer-brand{color:#eee9f2;font:500 10px var(--sans);letter-spacing:.07em}.footer-brand sup{font-size:7px}.site-footer a:not(.footer-brand){text-align:right}.journal-section{padding:70px 10.3vw;background:#0b0c10;border-top:1px solid #ffffff12}.journal-inner{max-width:1200px;margin:auto}.journal-heading{margin:0 0 25px;color:#eee;font-size:30px;font-weight:500;letter-spacing:-.05em}.journal-heading em{color:#a49bad;font-weight:400;font-style:normal}.blogger-section,.blogger-section .widget,.blogger-section .blog-posts{max-width:1200px}.journal-entry{display:grid;grid-template-columns:1fr 2fr;gap:30px;padding:18px 0;border-top:1px solid #ffffff20}.journal-entry h3{margin:0;color:#eee;font-size:16px;font-weight:500}.journal-entry p{margin:0;color:#96919e;font-size:11px;line-height:1.8}.journal-entry a:hover{color:#b49aff}.blogger-section .blog-pager,.blogger-section .status-msg-wrap{color:#aaa;font:9px var(--mono)}.blogger-section .blog-pager a{padding:8px}.modal-backdrop{position:fixed;z-index:110;inset:0;display:none;place-items:center;padding:24px;background:#050508e8;backdrop-filter:blur(10px)}.modal-backdrop.is-open{display:grid}.project-modal{position:relative;display:grid;width:min(950px,100%);max-height:90vh;grid-template-columns:1fr 1fr;overflow:auto;border:1px solid #ffffff18;background:#111116;animation:modal-up .25s ease}.modal-close{position:absolute;z-index:3;top:13px;right:13px;display:grid;width:38px;height:38px;place-items:center;border:1px solid #ffffff50;border-radius:50%;background:#0a0a0dc9;color:#fff;font-size:20px}.modal-art{min-height:430px}.modal-art .project-art{height:100%;min-height:430px}.modal-art img,.modal-art video{width:100%;height:100%;min-height:430px;object-fit:cover}.modal-content{padding:68px 38px 36px}.modal-content h2{margin:16px 0;font-size:clamp(35px,4vw,52px);line-height:.96;letter-spacing:-.07em}.modal-content>p{color:#aaa5b1;font-size:12px;line-height:1.8}.modal-note{margin:28px 0;padding:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);color:#aaa5b1;font-size:10px;line-height:1.8}.modal-note strong{display:block;margin-bottom:9px;color:#a49bad;font:8px var(--mono);letter-spacing:.1em}.modal-label{color:#a7a3ad;font:8px var(--mono);letter-spacing:.12em}.modal-back{border:0;background:none;color:#eee;font:8px var(--mono);letter-spacing:.1em}.js-ready .reveal{opacity:0;transform:translateY(22px);transition:opacity .8s ease,transform .8s cubic-bezier(.2,.8,.2,1)}.js-ready .reveal.is-visible{opacity:1;transform:translateY(0)}.blogger-system-area{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip-path:inset(50%)!important}.blogger-system-area .widget{display:none!important}@keyframes float{0%,100%{transform:translateY(0) rotate(-5deg)}50%{transform:translateY(-12px) rotate(6deg)}}@keyframes turn{to{transform:rotate(360deg)}}@keyframes modal-up{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:900px){.site-header{padding:0 5vw}.desktop-nav{gap:17px}.desktop-nav a,.sound-toggle,.skip-intro{font-size:8px}.hero-copy{left:7vw}.hero-title{font-size:clamp(58px,9.5vw,88px)}.awakening{padding-right:7vw;padding-left:7vw}.design-section,.motion-section,.work-section,.contact-section,.journal-section{padding-right:7vw;padding-left:7vw}.founder-section{padding-right:8vw;padding-left:8vw;gap:6vw}.feature-button:first-child .project-art{height:350px}.motion-section{grid-template-columns:.92fr 1.08fr}.motion-render{height:420px}.contact-content{gap:5vw}.contact-orb{right:5%;width:320px;height:320px}}
@media(max-width:650px){:root{scroll-padding-top:66px}.site-header{height:64px;padding:0 5vw;background:rgba(8,9,11,.92);backdrop-filter:blur(12px)}.wordmark{min-width:unset;gap:8px}.wordmark-icon{font-size:28px}.wordmark-name{font-size:8px}.desktop-nav{display:none}.mobile-actions{display:flex;align-items:center;gap:7px}.mobile-skip{display:flex;align-items:center;gap:5px;color:#d0cad8;font:7px var(--mono);letter-spacing:.07em}.menu-toggle{display:grid;width:40px;height:40px;place-items:center;border:0;background:none;color:white;font-size:21px}.mobile-menu{position:absolute;top:64px;right:0;left:0;flex-direction:column;gap:0;padding:12px 7vw 24px;border-bottom:1px solid #ffffff20;background:#0b0b10f7}.mobile-menu.is-open{display:flex}.mobile-menu a,.mobile-menu button{display:flex;min-height:43px;align-items:center;border:0;background:none;color:#d8d3de;font:9px var(--mono);letter-spacing:.1em}.mobile-menu .sound-toggle{gap:8px}.hero{height:max(760px,100svh);min-height:730px;max-height:980px}.hero-topline{top:87px;right:7vw;left:7vw;font-size:7px}.hero-topline span:last-child{max-width:135px;text-align:right;line-height:1.7}.hero:after{background:linear-gradient(90deg,#08090b73,transparent),linear-gradient(0deg,#08090b 1%,transparent 47%,#08090b55)}.hero-scene{top:12%;right:0;width:100%;height:72%;opacity:.85}.hero-copy{top:48%;left:7vw;width:88vw;transform:translateY(-22%)}.hero-eyebrow{width:90%;font-size:7px;margin-bottom:22px}.hero-title{font-size:clamp(47px,10.8vw,69px)}.hero-title em{margin-top:18px;font-size:clamp(22px,5.8vw,34px)}.hero-bottom{align-items:flex-end;gap:8px;margin-top:35px}.hero-tagline{font-size:10px}.begin-button{gap:8px;font-size:7px}.begin-icon{width:34px;height:34px}.hero-edge{display:none}.hero-scroll{bottom:22px;left:7vw;font-size:7px}.awakening{min-height:0;padding:95px 7vw 75px}.awakening-inner{grid-template-columns:1fr;gap:0}.awakening-art{height:300px;grid-row:2}.awakening-core{width:130px;height:130px}.awakening-orbit{width:280px;height:135px}.awakening-orbit.alt{width:290px;height:100px}.note-top{top:25px;left:6%}.note-bottom{right:1%;bottom:25px}.awakening-copy{grid-row:1}.awakening-copy h2{font-size:clamp(39px,10vw,60px)}.body-copy{font-size:12px}.side-note{display:none}.portal-section{height:650px}.portal-scene{top:49%;width:100vw;height:550px}.portal-caption .eyebrow{font-size:7px}.portal-caption h2{font-size:clamp(51px,12.8vw,79px)}.portal-caption>p:not(.eyebrow){font-size:7px}.portal-side{right:3vw;font-size:7px}.design-section{padding:90px 7vw 70px}.section-heading{display:block;margin-bottom:31px}.section-heading h2{font-size:clamp(49px,11.5vw,72px)}.section-intro{margin:18px 0 0}.discipline-row{gap:8px 11px;margin-bottom:13px;font-size:7px}.discipline-row span:not(:last-child):after{padding-left:9px}.feature-grid{grid-template-columns:1fr;gap:20px}.feature-button:first-child .project-art{height:320px}.feature-button.second{width:78%;justify-self:end;margin-top:0}.feature-button.second .project-art{height:255px}.feature-meta{font-size:6px}.section-endnote{margin-top:42px;font-size:7px}.motion-section{min-height:0;grid-template-columns:1fr;gap:5px;padding:90px 7vw 65px}.motion-copy h2{font-size:clamp(54px,12.5vw,80px)}.motion-copy h3{font-size:11px}.motion-copy>p:not(.eyebrow){font-size:11px}.discipline-pills span{padding:7px;font-size:6px}.motion-render{height:320px}.founder-section{grid-template-columns:1fr;gap:40px;padding:85px 8vw}.founder-visual{width:83%;justify-self:center}.portrait-placeholder{height:350px}.founder-copy h2{font-size:74px}.founder-index{left:-18px}.founder-detail{grid-template-columns:120px 1fr}.work-section{padding:92px 7vw}.work-heading{display:block;margin-bottom:30px}.work-heading h2{font-size:clamp(54px,12.5vw,81px)}.work-heading>p{margin:16px 0 0}.filters{gap:6px;margin-bottom:20px}.filter-button{padding:9px 10px;font-size:6px}.project-grid{column-gap:12px;row-gap:34px}.project-card:nth-child(even){margin-top:44px}.project-card .project-art{height:43vw;min-height:175px}.project-title{font-size:14px}.project-number{font-size:6px;letter-spacing:.05em}.project-open{width:28px;height:28px;font-size:13px}.concept-flag{top:7px;right:7px;padding:6px;font-size:6px}.art-label{bottom:8px;left:9px;font-size:6px}.honesty-note{margin-top:48px}.honesty-note p{font-size:7px}.contact-section{min-height:0;padding:90px 7vw 0}.contact-orb{top:7%;right:-9%;width:205px;height:205px;opacity:.45}.contact-heading h2{font-size:clamp(37px,8.8vw,56px)}.contact-heading h3{font-size:11px}.contact-content{grid-template-columns:1fr;gap:34px;margin-top:47px;padding-bottom:70px}.contact-aside>p{font-size:11px}.contact-signoff{margin-top:23px;padding-top:0}.form-grid{gap:21px 13px}.contact-form label{font-size:7px}.contact-form input,.contact-form select,.contact-form textarea{font-size:10px}.form-footer{align-items:flex-end}.form-notice{font-size:7px}.submit-button{min-height:42px;gap:7px;padding:0 11px;font-size:7px}.site-footer{min-height:95px;grid-template-columns:1fr 1fr;gap:16px 8px;padding:18px 0}.site-footer>span:nth-child(2){text-align:right;font-size:6px}.site-footer a:not(.footer-brand){font-size:6px}.site-footer>span:last-child{text-align:right;font-size:6px}.journal-section{padding:55px 7vw}.journal-heading{font-size:25px}.journal-entry{grid-template-columns:1fr;gap:9px}.project-modal{grid-template-columns:1fr;max-height:88vh}.modal-art,.modal-art .project-art,.modal-art img,.modal-art video{height:245px;min-height:245px}.modal-content{padding:32px 23px 25px}.modal-content h2{font-size:38px}.modal-backdrop{padding:12px}}
@media(max-width:380px){.hero-title{font-size:clamp(35px,9.5vw,38px)}.hero-bottom{align-items:flex-start;flex-direction:column;gap:17px}.filters{gap:5px}.filter-button{padding:8px 7px;font-size:6px}.form-grid{grid-template-columns:1fr}.form-footer{align-items:flex-start;flex-direction:column}.site-footer>span:nth-child(2){display:none}.feature-meta{font-size:6px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.js-ready .reveal{opacity:1;transform:none}.three-scene canvas{opacity:.75}}

body.script:
//
(function(){
  'use strict';
  /* ============================================================
     OWNER CONFIGURATION — change real contact/social information here.
     WhatsApp: digits only with country code (example format 919876543210).
     Keep empty until the correct contact details are ready.
     ============================================================ */
  var STUDIO_CONFIG={name:'SINGH CREATIVE STUDIO',founder:'Mukesh Singh',whatsapp:'',email:'',instagram:'https://www.instagram.com/YOUR_HANDLE/',behance:'https://www.behance.net/YOUR_HANDLE'};
  /* Project catalogue: edit titles, copy, categories and URLs here.
     image and video stay empty until real assets are supplied. */
  var PROJECTS=[
    {id:'form-study-01',title:'Form Study No. 01',category:'3D Animation',number:'01',description:'A study in balance, reflection and quiet movement. Polished metal forms meet an atmospheric field of light.',visual:'orb',label:'3D / CONCEPT STUDY',process:'An exploration of material, silhouette and light, designed as a still-frame concept for a future motion piece.',image:'',video:''},
    {id:'afterimage',title:'Afterimage',category:'Graphic Design',number:'02',description:'A typographic experiment about the persistence of a fleeting thought.',visual:'type',label:'TYPE / CONCEPT STUDY',process:'Expressive letterforms, paper-like grain and a limited palette bring an abstract idea into focus.',image:'',video:''},
    {id:'soft-geometry',title:'Soft Geometry',category:'Brand Identity',number:'03',description:'A visual identity direction exploring the tension between precision and softness.',visual:'geo',label:'IDENTITY / CONCEPT STUDY',process:'A flexible graphic language built from repeating forms, considered spacing and restrained colour.',image:'',video:''},
    {id:'light-matter',title:'Light / Matter',category:'Motion Graphics',number:'04',description:'An imagined motion-design frame where light behaves like a sculptural material.',visual:'light',label:'MOTION / CONCEPT STUDY',process:'A frame-by-frame visual study in contrast, luminous colour and dimensional composition.',image:'',video:''},
    {id:'object-orbit',title:'Object in Orbit',category:'3D Animation',number:'05',description:'A sculptural object suspended between industrial design and the impossible.',visual:'orbit',label:'3D / CONCEPT STUDY',process:'The object is staged as an exploratory CGI composition. This is a still concept image, not a video.',image:'',video:''},
    {id:'signal-form',title:'Signal / Form',category:'Graphic Design',number:'06',description:'An editorial poster concept built around rhythm, signal and an unapologetic focal point.',visual:'poster',label:'POSTER / CONCEPT STUDY',process:'Large-scale type and a vivid form create visual impact across a deliberately minimal layout.',image:'',video:''}
  ];
  var FILTERS=['All Projects','Graphic Design','3D Animation','Motion Graphics','Brand Identity'];
  var filterHost=document.getElementById('projectFilters'),grid=document.getElementById('projectGrid'),modal=document.getElementById('projectModal'),lastFocus=null;
  function artMarkup(project,extra){var image=project.image?'<img loading="lazy" src="'+project.image+'" alt="'+escapeText(project.title)+' project artwork"/>':'';var custom=image?' has-image':'';return '<span class="project-art art-'+escapeText(project.visual)+custom+'" role="img" aria-label="'+escapeText(project.title+' — '+project.label)+'">'+image+visualMarkup(project.visual)+'<span class="art-label">'+escapeText(project.label)+'</span></span>'}
  function visualMarkup(visual){var bits={orb:'<span class="art-orb"></span>',type:'<span class="art-type-word">AFTER<br/>IMAGE</span><i class="art-type-mark">///</i>',geo:'<span class="geo-ring"></span><span class="geo-block"></span><span class="geo-caption">FORM FOLLOWS FEELING</span>',light:'<span class="light-shape"></span><span class="light-label">LIGHT / MATTER</span>',orbit:'<span class="orbit-shape"></span><span class="orbit-line"></span>',poster:'<span class="poster-signal">SIGNAL<br/>/ FORM</span><span class="poster-sun"></span>'};return bits[visual]||bits.orb}
  function escapeText(text){return String(text).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]})}
  function renderFilters(active){filterHost.innerHTML='';FILTERS.forEach(function(label){var button=document.createElement('button');button.type='button';button.className='filter-button';button.textContent=label;button.setAttribute('aria-pressed',String(label===active));button.addEventListener('click',function(){renderFilters(label);renderProjects(label)});filterHost.appendChild(button)})}
  function renderProjects(active){var selected=PROJECTS.filter(function(project){return active==='All Projects'||project.category===active});grid.innerHTML='';selected.forEach(function(project){var card=document.createElement('article');card.className='project-card';var button=document.createElement('button');button.type='button';button.className='project-card-button';button.setAttribute('aria-label','View '+project.title+', '+project.category);button.setAttribute('data-project-id',project.id);button.innerHTML=artMarkup(project)+'<span class="project-meta"><span><span class="project-number">'+escapeText(project.number+' / '+project.category.toUpperCase())+'</span><span class="project-title">'+escapeText(project.title)+'</span></span><span aria-hidden="true" class="project-open">↗</span></span>';button.addEventListener('click',function(){openProject(project,button)});var flag=document.createElement('span');flag.className='concept-flag';flag.textContent=project.image?'PORTFOLIO IMAGE':'CONCEPT STUDY';card.appendChild(button);card.appendChild(flag);grid.appendChild(card)})}
  function openProject(project,trigger){lastFocus=trigger;document.getElementById('modalCategory').textContent=project.category+' — '+(project.image?'PORTFOLIO WORK':'DEMONSTRATION CONCEPT');document.getElementById('modalTitle').textContent=project.title;document.getElementById('modalDescription').textContent=project.description;document.getElementById('modalProcess').innerHTML='<strong>THE STUDY</strong>'+escapeText(project.process);var art=document.getElementById('modalArt');if(project.video){art.innerHTML='<video controls="controls" playsinline="playsinline" preload="none" aria-label="Video preview: '+escapeText(project.title)+'"><source src="'+project.video+'"/></video>'}else{art.innerHTML=artMarkup(project)}modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';document.getElementById('modalClose').focus()}
  function closeProject(){if(!modal.classList.contains('is-open'))return;modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');document.body.style.overflow='';document.getElementById('modalArt').innerHTML='';if(lastFocus)lastFocus.focus()}
